"Anyone remember why the sky is a portal?":"Ktoś pamięta, czemu niebo to portal?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Podobno jak skoczysz w szyb, wylecisz u wroga. Nie sprawdzam.",
"The Swarm painted their visors red again. Show-offs.":"Rój znowu pomalował wizjery na czerwono. Pozerzy.",
"Ore, ore… when do we get some oil?":"Ruda, ruda… a smar kiedy wydadzą?",
"I dreamt I was a toaster. It was peaceful.":"Śniło mi się, że jestem tosterem. Było spokojnie.",
"Quiet. Too quiet.":"Cicho. Zbyt cicho.",
