"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Witaj na meteorze! Jesteś robotem bojowym Konsorcjum. Rozejrzyj się myszą i idź: WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: naciśnij Shift — skok, przytrzymaj Shift — lot. Energia odnawia się na ziemi.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Strzelaj — LPM. Celuj — PPM: celniej i z przybliżeniem. Oddaj kilka strzałów.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Przeładowanie — R. Pociski biją najmocniej na średnim dystansie, 20–50 metrów.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Rakieta — Q. Na czołgi i budynki. Wystrzel rakietę.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"U góry jest zadanie od stratega. Biegnij po zielonych strzałkach: na trasie masz sprint. Przejmij punkt — stój przy latarni.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Twój oddział cię osłania: ich portrety i zdrowie są po lewej. Jeśli zostaną w tyle, poproszą, byś na nich poczekał.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — szybka zmiana jednostki bez opuszczania walki: skok do oddziału lub czołgu najbliżej starcia. Wypróbuj.",
"Next to a tank or turret press E to take control. Or just carry on.":"Obok czołgu lub wieżyczki naciśnij E, aby przejąć nad nimi kontrolę. Albo po prostu idź dalej.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Teraz strategia. Dotknij „◩ Strategia\" w prawym górnym rogu — widok z góry na pole bitwy.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Teraz strategia. Naciśnij {0} (albo „◩ Strategia\" w lewym górnym rogu) — widok z góry na pole bitwy.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"W trybie strategii pomaga ci Przewodnik: okno u góry mówi, co zrobić, ramka wskazuje przycisk, a pierścień — miejsce na mapie. Wykonaj trzy jego wskazówki.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Zaznacz oddział i dotknij zielonego przycisku „▶ Przejmij\" — wracasz do walki jako ten żołnierz. Gdy ty strzelasz, strateg AI dowodzi armią.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Zaznacz oddział i naciśnij {0} lub zielony „▶ Przejmij\" — wracasz do walki jako ten żołnierz (bez zaznaczenia — jako własny). Gdy ty strzelasz, strateg AI dowodzi armią.",
