"Left thumb — move, right thumb — look. Red button — fire.":"Lewy kciuk — ruch, prawy — rozglądanie się. Czerwony przycisk — ogień.",
"⇑ — jetpack: tap to hop, hold to fly. ◎ — aim.":"⇑ — jetpack: dotknij, by podskoczyć, przytrzymaj, by lecieć. ◎ — celowanie.",
"In the air, ⤓ is the jet brake.":"W powietrzu ⤓ to hamulec jetpacka.",
"Move and shoot: mouse to look, LMB to fire.":"Poruszaj się i strzelaj: mysz — rozglądanie się, LPM — ogień.",
"At the top is the AI strategist's order. Follow it: ×2 and ×3 XP, and completed orders can earn rewards. The green marker and chevrons lead the way.":"U góry jest rozkaz stratega AI. Wykonuj go: XP ×2 i ×3, a za wykonanie bywają nagrody. Zielony znacznik i szewrony prowadzą do celu.",
"Shift — jump pack: tap to hop, hold to fly. RMB — aim.":"Shift — jetpack: dotknij, by podskoczyć, przytrzymaj, by lecieć. PPM — celowanie.",
"In the air, C is the jet brake. Stop, turn with the mouse and thrust again.":"W powietrzu C to hamulec jetpacka. Zatrzymaj się, obróć się myszą i dodaj ciągu jeszcze raz.",
"Enemy vehicle or structure nearby. A rocket is best against them.":"W pobliżu wrogi pojazd lub budowla. Najlepsza przeciw nim jest rakieta.",
"Enemies are bunched up — throw a grenade.":"Wrogowie zbili się w kupę — rzuć granat.",
"Lots of hostiles — trigger Reflex: time slows down and you can pick them off.":"Wielu wrogów — włącz refleks: czas zwolni, a ty zdążysz ich wszystkich zdjąć.",
"Aim at the enemy cluster and call in a strike.":"Wymierz w skupisko wrogów i wezwij ostrzał.",
"Targets are far — the railgun is stronger at long range.":"Cele są daleko — railgun jest silniejszy na dużym dystansie.",
"You have a temporary heavy MG — use it before it is recalled.":"Masz tymczasowy ciężki karabin maszynowy — używaj go, zanim go odwołają.",
"Parkour: C while running — slide, jump at a ledge — climb it, jump next to a wall in the air — wall-jump.":"Parkour: C w biegu — wślizg, skok przy krawędzi — wspinaczka, skok przy ścianie w powietrzu — odbicie od ściany.",
"Bullets hit hardest at 20–50 m. Point-blank and long range are much weaker — for enemies too.":"Pociski biją najmocniej z 20–50 m. Z bliska i z daleka są dużo słabsze — u wrogów też.",
"Your robot is badly damaged. Get out of the fire — armor self-repairs out of combat.":"Twój robot jest mocno uszkodzony. Zejdź z linii ognia — poza walką pancerz naprawia się sam.",
"One of our tanks is close. Walk up and press E to take control.":"Obok jest nasz czołg. Podejdź i naciśnij E, by nim sterować.",
"Man the turret — press E next to it.":"Zajmij wieżyczkę — E obok niej.",
"It is quiet here. Switch to a squad or vehicle closer to the fight.":"Tu jest cicho. Przełącz się na oddział lub pojazd bliżej walki.",
"Reload early while no enemies are around.":"Przeładowuj z wyprzedzeniem, gdy nie ma wrogów.",
"Sprint right along the strategist's green chevrons — you run faster on his route.":"Biegnij prosto po zielonych szewronach stratega — na jego trasie biegniesz szybciej.",
"\"◩ Strategy\" button — top view: build the base, order troops, command squads.":"Przycisk „◩ Strategia\" — widok z góry: buduj bazę, zamawiaj wojska, dowodź oddziałami.",
"Strategy mode: build the base, order troops, call strikes and command squads. The same key there possesses the selected unit.":"Tryb strategii: buduj bazę, zamawiaj wojska, wzywaj ostrzały i dowodź oddziałami. Ten sam klawisz działa tam jako „Przejmij\" dla zaznaczonej jednostki.",
"Want full command? Turn off the AI strategist — then you give the orders.":"Chcesz dowodzić sam? Wyłącz stratega AI — wtedy rozkazy wydajesz ty.",
"Third-person view — to see your robot.":"Widok z trzeciej osoby — żebyś widział swojego robota.",
"Tank: {0} — barrage at your aim point, {1} — smoke screen, {2} — overdrive. {3} — back to infantry.":"Czołg: {0} — salwa w punkt celowania, {1} — zasłona dymna, {2} — forsaż. {3} — z powrotem do piechoty.",
"Plenty of targets — fire a barrage.":"Celów jest dużo — daj salwę.",
"Drone: {0}/{1} — up/down, LMB — fire, {2} — ram your aim point.":"Dron: {0}/{1} — wyżej/niżej, LPM — ogień, {2} — taranowanie punktu celowania.",
"Select a squad — LMB, drag a box or a card on the left. RMB on the ground — attack-move ⚔, on an enemy — attack, on a point — capture.":"Zaznacz oddział — LPM, ramką albo kartą po lewej. PPM na ziemi — atak w marszu ⚔, na wrogu — atak, na punkcie — przejęcie.",
"Squads have abilities: grenades, jet leap, suppression, repair. Tanks: barrage, smoke, overdrive.":"Oddziały mają zdolności: granaty, skok na jetpackach, tłumienie ognia, naprawa. Czołgi: salwa, dym, forsaż.",
"Plenty of ore — select the HQ or a factory and order troops in its panel on the right.":"Rudy jest dużo — wybierz HQ lub fabrykę i zamów wojska w jej panelu po prawej.",
"Command points are piling up — \"Powers\" tab: recon, artillery, squad drop pod, orbital strike.":"Punktów dowodzenia przybywa — zakładka „Uderzenia\": zwiad, ostrzał artyleryjski, kapsuła desantowa z oddziałem, uderzenie orbitalne.",
"Only builders construct buildings: select a builder (button in the Build tab or a building key), then click the spot. An extractor (C) on a glowing vein — more ore.":"Budynki stawiają tylko inżynierowie: zaznacz inżyniera (przycisk w zakładce „Budowa\" lub klawisz budynku), potem kliknij miejsce. Ekstraktor (C) na jarzącej się żyle — więcej rudy.",
"Click \"ORE\" at the top left — where ore comes from and how to boost income.":"Kliknij „RUDA\" w lewym górnym rogu — skąd bierze się ruda i jak przyspieszyć dochód.",
"Ctrl+1…9 — save a group, 1…9 — select it, double-tap — jump the camera.":"Ctrl+1…9 — zapamiętaj grupę, 1…9 — wybierz ją, podwójne naciśnięcie — kamera do niej.",
"Select a unit and tap the green \"▶ Possess\" below (or double tap) to fight yourself. \"◩ Strategy\" brings you back.":"Zaznacz jednostkę i dotknij zielonego „▶ Przejmij\" na dole (albo dotknij dwukrotnie) — walczysz sam. „◩ Strategia\" wraca tutaj.",
"Select a unit and press the green \"▶ Possess\" below or {0} (or double-click) to fight yourself. In battle {1} brings you back.":"Zaznacz jednostkę i naciśnij zielone „▶ Przejmij\" na dole albo {0} (albo kliknij dwukrotnie) — walczysz sam. W walce {1} wraca do strategii.",
"Grey buttons can be pressed too: you will see what is missing, how long to wait and how to fix it.":"Szare przyciski też można naciskać: pokażemy, czego brakuje, jak długo czekać i jak to naprawić.",
"RMB on the ground — rally point for this building's new troops.":"PPM na ziemi — punkt zbiórki dla nowych wojsk tego budynku.",
"RMB — attack-move ⚔: they stop to fight enemies they meet, then continue. Double RMB — march »: run without stopping, firing on the move. Hold/Retreat — \"More orders ▾\".":"PPM — atak w marszu ⚔: napotkawszy wroga, zatrzymają się i będą walczyć, potem pójdą dalej. Podwójny PPM — marsz »: biegiem, bez zatrzymywania, strzelając w biegu. Trzymaj pozycję/Odwrót — „Więcej rozkazów ▾\".",
"Camera: drag with a finger, two fingers — zoom and rotate, drag on the minimap too.":"Kamera: przeciągaj palcem, dwoma — skala i obrót, minimapę też można przeciągać palcem.",
"Camera: WASD and screen edges, Q/E rotate, wheel zoom (to cursor), MMB orbit, minimap — click or drag, Space — to the latest alert.":"Kamera: WASD i krawędzie ekranu, Q/E — obrót, kółko — wysokość (do kursora), ŚPM — obracanie, minimapa — kliknięcie lub przeciąganie, Spacja — do ostatniego alarmu.",
