"Only builders build. No builder selected — the button picks the nearest idle one and starts the blueprint; then LMB on a spot.":"Buduje tylko inżynier. Jeśli inżynier nie jest zaznaczony, przycisk wybierze najbliższego wolnego i włączy projekt; potem LPM na miejscu.",
