"Then click (tap) the ground: they move and fight on the way. On an enemy — attack it. Same as RMB.":"Potem kliknij (dotknij) ziemię: idą i strzelają po drodze. Na wroga — atakują go. To samo co PPM.",
"Run":"Biegiem",
"Then click (tap) the ground: they run without engaging. Same as double RMB.":"Potem kliknij (dotknij) ziemię: biegną, nie wdając się w walkę. To samo co podwójny PPM.",
