"Selected groups stay put and return fire.":"Zaznaczone grupy stoją w miejscu i odpowiadają ogniem.",
"Retreat":"Odwrót",
"Run back to the HQ (or nearest outpost) without engaging.":"Biegiem z powrotem do HQ (lub najbliższej placówki), bez walki.",
"Squads jet up through the dome portal and land at the enemy.":"Oddziały wzlatują na jetpackach przez portal kopuły i lądują u wroga.",
"Control the selected trooper, tank or turret yourself. The same key in battle brings you back to strategy.":"Steruj zaznaczonym żołnierzem, czołgiem lub wieżyczką z pierwszej osoby. Ten sam klawisz w walce wraca do strategii.",
"4 troopers: assault, heavy gunner, rocketeer, medic.":"4 żołnierzy: szturmowiec, ciężki strzelec, granatnik, medyk.",
