"New in v6.3":"Nowości w v6.3",
"New in v6.2":"Nowości w v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Nowy wygląd rudy: żyły to świecące szmaragdowe, szlifowane kryształy na czarnym bazalcie z iskrami i zieloną mgiełką; ekstraktor to sześciokątny cokół z kopułą w plaster miodu i kratownicową wieżą ze zielonym światłem-latarnią (pasek i proporczyk w kolorze drużyny)",
"New in v6.1":"Nowości w v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Preferowana klasa jak w Battlefield (U, cyfry po śmierci): odrodzisz się nią, jeśli jest dostępna",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Pojazdy z pierwszej osoby (V — z zewnątrz/z kabiny); delikatne wspomaganie celowania — w Ustawieniach",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Łatwa ucieczka z Rdzenia: Spacja — do szybu, B — kapsuła na powierzchnię; efekty zdolności resetują się po śmierci",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Niekończący się rozwój: generałowie i Marszałek ★, poziomy kariery, mistrzostwo broni i dodatki, medale, codzienne kontrakty — ekran „Kariera”",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Strategia: płynny zoom kółkiem, ikony i podpisy nad jednostkami (Alt — wszystkie), panel „Wojska / Budynki” po lewej",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"PPM — idź i walcz po drodze, 2× PPM — marsz ze strzelaniem w ruchu; rzadkie rozkazy — w „Więcej rozkazów ▾”; przyciski się nie dublują",
"New in v6":"Nowe w v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Strzelanie jak w shooterach: natychmiastowe pociski, karabin 720 strz./min, karabin maszynowy, odrzut, celownik na PPM, magazynki i przeładowanie R, znaczniki trafień",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Cięższa grawitacja, responsywny jetpack, zryw na Z lub 2× jetpack w powietrzu; przy zmianie jednostki broń już nie leci razem z tobą",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Inżynierowie: zaznacz inżyniera, wybierz budynek, postaw projekt; ekstraktory na żyłach rudy; kliknij „RUDA” — skąd dochód i jak go zwiększyć",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Szare przyciski są klikalne — wyjaśnią powód i zaproponują rozwiązanie; większe przyciski, pasek „W toku”, „▶ Przejmij”, Tab — jeden klawisz trybu",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Kamera strategii bez szarpnięć i przewrotów, zoom do kursora, minimapę można przeciągać",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Nowy sprzęt: najeźdźca „Szakal”, wieloprowadnicowa wyrzutnia rakiet „Grad” (rakiety samonaprowadzające), moździerz „Młot”; Rój dostaje „Osę”, „Ul”, „Trebusz”",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Strateg nie zmienia rozkazów i nie spamuje głosem; walki toczą się blisko ciebie; B — przerzut, Shift+B — w sam środek walki; kompas, H — który cel",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Swobodna gra (K) i „działam sam” (J), F2 — presety; Esc — pauza i powrót; zapisy: sloty, eksport i import pliku",
"New in v5.3":"Nowe w v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Lot: grawitacja daleko od meteoru jest silniejsza, C w powietrzu — hamulec, ciąg skręca ostrzej; koniec z „zawieszaniem się” w portalu",
"New in v5":"Nowe w v5",
"Endless war by default and battle scale: normal, large, epic":"Domyślnie nieskończona wojna i skala bitew: zwykła, duża, epicka",
