"Squadmates with callsigns: portraits, health and live chatter":"Oddział z pseudonimami: portrety, zdrowie i żywe rozmowy",
"Fog of war in strategy, friends and foes outlined differently":"Mgła wojny w strategii, swoi i wrogowie podświetleni inaczej",
"Camera fly-over when switching, portal aurora instead of rings":"Przelot kamery przy przełączaniu, zorza portalu zamiast pierścieni",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Zadania poboczne, skrót przez niebo, moduły pierwszej ekspedycji z zapasami, kryształy, lód w kraterach, burze pyłowe",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Szkolenie, tryb kinowy z nagrywaniem filmów, pojazdy eskorty od stratega",
