"Grenade: hold G to see the arc and blast circle; drag on the button to aim; release to throw.":"Granat: przytrzymaj G — zobaczysz łuk i krąg wybuchu; przesuwaj palcem po przycisku — kąt; puść — rzut.",
"Grenade: hold {0} for the arc and blast circle, release to throw. Range — by view angle, wheel — power, RMB — underhand.":"Granat: przytrzymaj {0} — łuk i krąg wybuchu, puść — rzut. Zasięg — kątem patrzenia, kółko — siła, PPM — pod nogi.",
"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"Granaty: przytrzymaj G — łuk lotu, punkt i krąg wybuchu, dystans; puść — rzut. Zasięg kątem patrzenia, kółko — siła, PPM — pod nogi",
"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"Granaty odbijają się i toczą po zboczach, wybuch po 2.5 s; 2 granaty, odnowienie 9 s; ikona ostrzegawcza o wrogim granacie w pobliżu",
"Grenade: hold — arc and blast point, release — throw · tank overdrive":"Granat: przytrzymaj — łuk i punkt wybuchu, puść — rzut · forsaż czołgu",
"G — hold: see the arc and blast circle, release to throw. 2.5 s fuse, 2 grenades.":"G — przytrzymaj: widać łuk i krąg wybuchu, puść — rzut. Wybuch po 2.5 s, 2 granaty.",
"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"Granat ({0}): przytrzymaj — łuk lotu, punkt i krąg wybuchu, dystans; puść — rzut; krótkie dotknięcie — rzut od razu. Zasięg kątem patrzenia, kółko — siła, PPM — pod nogi. Telefon: przytrzymaj G i przesuwaj palcem.",
