"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Dotknij „Celownik” — przybliżenie. Kolejne dotknięcie — powrót.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Oddział podąża za tobą. Otwórz ☰ → „Pauza” → kafelek „Oddział ze mną” — zmieni się na „Działam solo”.",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Inżynier wybrany — dotknij „◆ Wydobywaj kryształy” na jego karcie na dole (lub dotknij zielonych kryształów).",
"Training complete!":"Szkolenie ukończone!",
"steps":"kroków",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Umiesz budować bazę, zamawiać wojska, dowodzić i wskakiwać do walki. Dalej — prawdziwy mecz: Kurator będzie podpowiadał w trakcie gry.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Umiesz się poruszać, latać, strzelać, chować się i dowodzić oddziałem. Dalej — prawdziwy mecz.",
