"Again":"Jeszcze raz",
"done":"ukończono",
"you are on PC: keyboard and mouse":"grasz na PC: klawiatura i mysz",
"you are on a phone: touch screen":"grasz na telefonie: ekran dotykowy",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Bezpieczna piaskownica: wrogowie to nieruchome manekiny, nikt do ciebie nie strzela. Krok liczy się dopiero, gdy sam wykonasz daną czynność.",
"Show others (training for the other device)":"Pokaż inne (szkolenia na drugie urządzenie)",
"Old training (v7.1)":"Stare szkolenie (v7.1)",
"Back to the normal device mode":"Wróć do normalnego trybu urządzenia",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Szkolenie na drugie urządzenie przeładuje stronę w jego trybie (PC — mysz i klawiatura, telefon — dotyk; na PC dotyk wygodnie sprawdzić w Chrome: F12 → ikona telefonu).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Szkolenie ×4: osobne lekcje krok po kroku „Strateg” i „Strzelec” na PC i na telefon. Bezpieczna piaskownica z manekinami, podświetlenie potrzebnego przycisku, strzałki, animowane klawisze, mysz i gesty; krok zalicza się tylko za prawdziwe działanie, „powtórz krok”, postęp u góry i nagroda na końcu",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Menu Szkolenie samo pokazuje lekcje na twoje urządzenie; „Pokaż inne” — wszystkie cztery na dowolnym urządzeniu; „Stare szkolenie (v7.1)” zostało",
"New in v7.2":"Nowość w v7.2",
"NEW IN v7.2":"NOWOŚĆ W v7.2",
"No grenades left":"Skończyły się granaty",
"Rocket and grenade recharging · {0} s":"Rakieta i granat się ładują · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Z lewej — ruch, z prawej — rozglądanie · dotknięcie wroga — rakieta / granat · 2 dotknięcia — refleks · 3 dotknięcia — ostrzał artyleryjski",
"Less":"Mniej",
"More":"Więcej",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Obok jest pojazd lub budowla wroga — dotknij ją: poleci rakieta.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Dużo wrogów — szybko dotknij 2 razy wolne miejsce po prawej: refleks spowolni czas.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Namierz skupisko wrogów i dotknij 3 razy — ostrzał artyleryjski.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Lewy palec — ruch, prawy — rozglądanie. Celownik na wrogu — ogień sam.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ z lewej przy krawędzi — jetpack: dotknij, by podskoczyć, przytrzymaj, by lecieć.",
"Old v7.2 layout":"Stary układ v7.2",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Przesuwaj palcem po prawej połowie ekranu — pod palcem pojawi się drążek rozglądania.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Dotknij lewej strony i przesuwaj palec — pod palcem pojawi się drążek. Dojdź do zielonego znacznika.",
"Hold the \"Jet\" button at the left edge.":"Przytrzymaj przycisk „Jet” przy lewej krawędzi.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Prawym drążkiem namierz manekina — twój żołnierz strzela sam, gdy celownik jest na celu.",
"Tap the dummy on the screen — a rocket flies.":"Dotknij manekina na ekranie — poleci rakieta.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Dotknij manekina — poleci granat (łukiem, prosto w cel).",
"Double tap an empty spot on the right quickly.":"Szybko dotknij 2 razy wolne miejsce po prawej.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Tryb lekki dla słabych telefonów: niższa rozdzielczość, bez cieni i zniekształceń, o połowę mniej botów i cząsteczek, limit 30 FPS; sam obniża rozdzielczość, gdy FPS < 25. Na telefonie domyślnie włączony (Ustawienia → Grafika → „Tryb lekki”; lub ?lite=1 / ?lite=0 w linku).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Telefon: nowy układ sterowania. Z lewej — ruch, z prawej — rozglądanie (oba drążki pojawiają się pod palcem). Sam lewy palec — „auto”; gdy używasz prawego, żołnierz strzela sam tylko wtedy, gdy celownik jest na wrogu. Dotknięcie wroga — rakieta lub granat, 2 dotknięcia — refleks, 3 dotknięcia — ostrzał artyleryjski. Automatyczne przeładowanie. Jetpack — przycisk przy lewej krawędzi. Dolne rogi są wolne, minimapa w rogu, podpowiedzi zamykasz krzyżykiem, zadanie można zwinąć. Stary układ: Ustawienia → Telefon.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Podpowiedzi (okienka i Przewodnik) — jeden przełącznik w ustawieniach. Kim grasz (typ żołnierza lub pojazdu) — napis „Ty: …” w HUD. Optyka karabinu i karabinu maszynowego jest przezroczysta. Panel „Arsenał” jest zadokowany po prawej, można go zwinąć i wyłączyć. Tryb „sam bez oddziału” (J) usunięto. Głos stratega nie powtarza już tej samej kwestii. Czołgi mają wskaźnik wieży względem kadłuba. Kursor nie znika już na początku szkolenia ze strategii.",
