"Possess squads (infantry)":"Przejmuj oddziały (piechota)",
"Possess vehicles and drones":"Przejmuj pojazdy i drony",
"On the gun: {0}. The AI drives, you shoot. {1} — get off":"Za działem: {0}. Pojazdem kieruje AI, ty strzelasz. {1} — zejdź",
