"Advanced: class order":"Zaawansowane: kolejność klas",
"Voice of hints and curator":"Głos podpowiedzi i Przewodnika",
"Advanced: custom class order":"Zaawansowane: własna kolejność klas",
"Voice of hints & curator":"Głos podpowiedzi i Przewodnika",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Telefon: trzy tryby drążków. Tylko lewy — „auto” (silny magnes, ale słabsze pociski). Tylko prawy — celownik włącza się sam, silniejszy magnes, celniejszy ogień. Oba naraz — bez celownika, słabszy magnes i celność. Przycisk 👁 po prawej — ukryj/przywróć interfejs.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Telefon: uproszczona strategia — tylko inżynier i budynki. Z lewej karty (inżynier, kwatera główna, koszary…): dotknięcie — kamera leci do niego, na dole od razu widać, co budować/produkować. „Do walki” — u góry po lewej. Armia walczy sama. Pełna strategia — Ustawienia → Telefon.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Przejmowanie — dwa przełączniki: „Oddziały” i „Pojazdy” (na telefonie pojazdy są domyślnie wyłączone — kieruje nimi AI). Gdy pojazdy są wyłączone, E (na telefonie — przycisk po prawej) obok własnego pojazdu — siądź za jego działem: pojazd jedzie sam, ty strzelasz. Stara „własna kolejność klas” jest w „Zaawansowanych”. Przy przejęciu jednostka odpowiada przez radio.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Inteligentne podpowiedzi: podstawowe same wygasają po 2. uruchomieniu, ale gra podpowie funkcję, której wciąż nie używasz. Przełączniki: podstawowe / zaawansowane / rzadkie, osobno — głos podpowiedzi i Przewodnika.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Refleks ładuje się od zabójstw (seria — mocniej). Koledzy z oddziału zostali w tyle lub zginęli — strateg zrzuca ci nowych (drożej niż zwykłe uzupełnienie). Grafika i dźwięk v7.2gfx zostały włączone: kłębiaste wybuchy, dym, szczątki, akustyka szybów i kraterów. Data kompilacji jest teraz prawdziwa.",
