"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Kariera i zapisy pozostają bez zmian. W walce to samo menu to przycisk „🛠 Menu” u góry po prawej{0}.",
"New developer match":"Nowy mecz dewelopera",
"all unlocked, endless ore, instant build, arsenal":"wszystko odblokowane, ruda bez końca, natychmiastowa budowa, arsenał",
"Trainings — all 4":"Szkolenia — wszystkie 4",
"PC and phone (strategy and shooter)":"PC i telefon (strategia i strzelec)",
"Cinema: split screen":"Kino: podzielony ekran",
"strategist bot left, shooter bot right":"po lewej bot-strateg, po prawej bot-strzelec",
"Cinema: everything built":"Kino: wszystko zbudowane",
"both bases built and upgraded — for footage":"obie bazy zbudowane i ulepszone — do nagrań",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Tryb kinowy — podzielony ekran: po lewej bot-strateg (widok z góry na bazę i armię), po prawej bot-strzelec z perspektywy pierwszej osoby. Przyciski na dole (klawisze S, P): „Podzielony ekran” i „★ Wszystko zbudowane” — obie bazy zbudowane i ulepszone do nagrań.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Rdzenia i tuneli przez meteor już nie ma — meteor jest lity, walka toczy się tylko na powierzchni.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Telefon: 👁 chowa interfejs, ale zostawia jetpack, ⇆, drążki i znacznik zadania. „◎ Celownik” (tylko prawy palec) — wyraźnie silniejszy i szerszy magnes; siłę magnesu dla trzech trybów ustawisz w Ustawienia → Sterowanie → „Zaawansowane”. Przy działku pojazdu przycisk nazywa się „Zejdź”.",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Szkolenie: na telefonie tylko szkolenia mobilne, na PC — tylko PC. Wszystkie 4 są w menu „🛠 Deweloper”. Tryb dewelopera i Arsenał to teraz jedno menu (w walce — „🛠 Menu” w prawym górnym rogu, na PC także F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Style grafiki „Dendy (8-bit)” i „16-bit”: Ustawienia → Grafika → „Styl grafiki” (szczegóły — przycisk ⚙). Jeśli w pierwszych ~10 s meczu FPS spadnie poniżej 24, Dendy włączy się samo (poniżej 20 — jeszcze większy piksel, 120 linii); komunikat „wróć do normalnej” przywraca zwykłą grafikę na stałe. Twój własny wybór w menu zawsze ma pierwszeństwo.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"Modele 3D otoczenia (ruiny, wraki, fortyfikacje) — tylko te z dobrymi ocenami, ładowane na żądanie. Wyłączysz je w: Ustawienia → Grafika → „Nowe modele 3D otoczenia”.",
