"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Budowa przez żołnierzy: E (na telefonie „Wejdź”) przy własnej budowie — żołnierz buduje sam, koledzy z oddziału obok pomagają. Jeśli inżynierowie są zajęci, strateg sam poprosi o pomoc — znacznik „BUDOWA”.",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Znaczniki stratega: strateg stawia ⌖ na skupisku wrogów obok ciebie — po 8 s uderza tam artyleria, a pobliskie sojusznicze MLRS „Grad” oddają salwę. Twój własny ostrzał artyleryjski z trybu strategii też dostaje wsparcie „Gradów”.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Skrytki z bronią w kontenerach towarowych i rozbitych satelitach (📦 widać z 70 m): E — ciężki karabin maszynowy na 90 s, pociski zapalające lub rakiety, plus komplet granatów. Czołganie: Ctrl — padnij / wstań (niżej, stabilniej celuje się, ale wolno).",
