"Link copied":"Link skopiowany",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"„▶ Graj teraz” — pierwszy przycisk menu: krótki przelot pod niebem-portalem i od razu do walki (pominiesz dowolnym klawiszem lub dotknięciem).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Trafienia czuć: metaliczny dźwięk i iskry, znacznik zabójstwa przy celowniku (strzał w głowę — żółty), seria ×N, płynne wstrząsy od wybuchów, slow-mo przy ważnych zabójstwach. Trzęsienie, slow-mo i podpowiedź wyłączysz w Ustawieniach.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Podsumowanie meczu: czas, zniszczenia, najlepsza seria, ★ MVP i najlepszy oddział, karta meczu — „⇪ Udostępnij”, PNG lub link do gry.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Podpowiedź „co robić teraz” po lewej pod zasobami: rozkaz stratega, punkt do przejęcia, atak Roju. ✕ lub F7 — zwiń.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Walka zapisuje się sama, gdy zamkniesz lub zwiniesz kartę — w menu „⟲ Kontynuuj”.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"Wersja v7.5 została w menu „🕘 Wersja gry” — gdyby nowa ci się nie spodobała. Wysyłane są teraz anonimowe statystyki (bez imion i e-maili); wyłączysz je w Ustawieniach.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"„Graj teraz”, odczuwalne trafienia, podsumowanie meczu z kartą, podpowiedź „co robić”, autozapis",
"and older: v7.5, v7.4, milestones v1–v7.0":"i starsze: v7.5, v7.4, kamienie milowe v1–v7.0",
"New in v7.6":"Nowości w v7.6",
"NEW IN v7.6":"NOWOŚCI W v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Wybór frakcji przed meczem: „Konsorcjum” (ciężka piechota w pancerzach wspomaganych, pancerz i artyleria) lub „Rój” (szybkość, watahy dronów, ciężkie strzały ze zniekształceniem). SI gra drugą. Wybór jest zapamiętywany.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Każda frakcja ma własne pojazdy i unikalne ulepszenia: Konsorcjum — czołg „Nosorożec” i „Płyty ceramitowe”, Rój — „Wataha dronów” i „Jetpacki fazowe”. Balans sprawdzony meczami botów.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Kratery po wybuchach: artyleria, rakiety i działa czołgów wykopują w meteorze doły — można po nich chodzić i jeździć oraz chować się w nich w poszukiwaniu osłony.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Widok z trzeciej osoby dla żołnierza (V, zapamiętywany; na telefonie — Sterowanie) i płynna kamera pojazdów ze znacznikiem, gdzie trafi działo.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"Wersja v7.6 zostaje w menu „🕘 Wersja gry” — gdyby nowa ci nie podeszła.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Frakcje Konsorcjum / Rój z wyborem przed meczem, kratery po wybuchach, widok z trzeciej osoby",
