"Anomaly ahead! The vein is singing — go around!":"Anomalia z przodu! Żyła śpiewa — omijamy!",
"Hear that hum? A singing vein. Keep clear!":"Słyszycie ten pomruk? Śpiewająca Żyła. Nie podchodzić!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Anomalia! Powietrze wiruje — to Odmęt, omiń go!",
"Rocks floating in the air… A whirlpool! Stay out!":"Kamienie wiszą w powietrzu… Odmęt! Nie pchaj się tam!",
"Anomaly ahead — it is crackling with current!":"Anomalia z przodu — trzeszczy od prądu!",
"Rods and lightning — a Crackler. It loves armour!":"Pręty i błyskawice — Trzaskacz. Uwielbia pancerz!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomalia! Ziemia drży od żaru — Żarnik!",
"Careful, a Brazier underfoot!":"Ostrożnie, pod nogami Żarnik!",
"Anomaly — green mist! Acid, hold your breath!":"Anomalia — zielona mgła! Kwas, wstrzymaj oddech!",
"The mist is drifting our way, go around!":"Mgła pełznie w naszą stronę, omijamy!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Anomalia! Powietrze jak szkło — Soczewka, wygina pociski!",
"Everything is warping… a Lens nearby!":"Obraz się wypacza… Soczewka blisko!",
"Ha! An enemy walked right into the anomaly!":"Ha! Wróg wlazł prosto w anomalię!",
"Got him! Lure them into anomalies!":"Mam go! Zwabiaj ich w anomalie!",
"Beautiful zap! One less tin can.":"Pięknie błysnęło! Minus jedna puszka.",
"The anomaly got me!":"Anomalia mnie złapała!",
"Ow! Don't go in there!":"Au! Nie właźcie tam!",
