" — close":" — zamknij",
"Supply drop":"Zrzut zaopatrzenia",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Zrzuca skrzynię przy waszych siłach: amunicja, granaty, rakiety, części do broni, zestaw naprawczy.",
"\"Grad\" rocket strike":"Uderzenie „Gradu”",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 rakiet na dużą powierzchnię po 3 sekundach — szybciej i szerzej niż ostrzał artyleryjski.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Wsparcie: skrzynia, zwiad, „Grad”, ostrzał artyleryjski (potem 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"UWAGA: „Grad” Roju uderza w wasz rejon!",
"Warning! Rocket salvo on our position!":"Uwaga! Salwa rakietowa na naszą pozycję!",
"take the supply crate":"weź skrzynię zaopatrzenia",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Anomalie na meteorze (fala 1): „Śpiewająca Żyła” — świecący zielony kryształ, huczy i rytmicznymi impulsami razi wszystkich w pobliżu; „Odmęt” wciąga i ciska, „Trzaskacz” wyładowuje łuki między prętami, „Żarnik” wybucha płomieniem pod nogami, „Kwaśna mgła” i „Soczewka” (wygina pociski i obraz) dryfują wokół.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomalie wyczuwa się z wyprzedzeniem (pomruk, blask, drżenie powietrza). Rozładuj granatem, rakietą lub śrubą (E przy anomalii): uśpi się, a czasem zostawi artefakt z plusem i minusem. Oddział ostrzega przez radio, a wrogowie (i swoi) czasem w nie wpadają — zwabiaj ich!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Wsparcie za punkty dowodzenia: 4 w walce (📡 na telefonie) — zrzut skrzyni, skan zwiadowczy, uderzenie „Gradu”, ostrzał artyleryjski na celowniku. Strateg widzi anomalie na mapie dopiero po zwiadzie.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Skrzynie zaopatrzenia w ruinach dawnych wypraw, przy kwaterach głównych i obok ukończonych budynków: amunicja, granaty, rakiety, części do broni (odblokowują dodatki).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"Wersja v7.7 zostaje w menu „🕘 Wersja gry”. Anomalie można wyłączyć w Ustawieniach.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomalie („Śpiewająca Żyła” i 5 kolejnych), rozładowanie śrubą i granatem, artefakty, wsparcie za PD, skrzynie zaopatrzenia",
"and older: v7.7, v7.6, milestones v1–v7.0":"i starsze: v7.7, v7.6, kamienie milowe v1–v7.0",
"New in v7.8":"Nowości w v7.8",
"NEW IN v7.8":"NOWOŚCI W v7.8",
"Close":"Zamknij",
"Anomalies on the meteor":"Anomalie na meteorze",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ w rogu otwiera menu pauzy: Wznów, Zacznij od nowa, Szkolenie, Grafika, Ustawienia, Menu główne (z potwierdzeniem). Telefon: ☰ w prawym górnym rogu (akcje bojowe — kafelek „⚡ Akcje”); PC: przycisk „☰ Menu” w prawym górnym rogu lub Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Grafika domyślnie zawsze jest zwykła — Dendy tylko jeśli ją wybierzesz: przełącznik „Grafika: Zwykła / Dendy (8-bit) / 16-bit” jest w menu głównym i w pauzie. Jeśli gra mocno zwalnia, pojawi się podpowiedź z przyciskiem „Włącz Dendy”.",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Telefon i tablet: przycisk akcji „✋” po prawej pojawia się tylko wtedy, gdy w pobliżu jest coś do zrobienia — „Weź” (skrytka, skrzynia), „Wsiądź” (pojazd, wieżyczka, działo), „Buduj”, „Zejdź”, „Śruba” przy anomalii. Można też po prostu dotknąć podświetlonego obiektu.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Telefon, strategia: przytrzymaj palec ~0,3 s (telefon zawibruje, pojawi się żółty pierścień) i przeciągnij — ramka zaznaczenia; zwykłe przesunięcie rusza kamerą. Jest też przycisk „Ramka” po prawej; w szkoleniu krok „Ramka” zalicza też wybór oddziału dotknięciem.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Telefon: małe przyciski łatwiej trafić, lista wsparcia 📡 jest większa, panele strategii nie zasłaniają już pauzy ani podsumowań. Wersja v7.8 zostaje w menu „🕘 Wersja gry”.",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"Menu ☰ na telefonie i PC, brak automatycznego Dendy, przycisk „✋” na telefonie, zaznaczanie ramką na telefonie",
"16-bit":"16-bit",
"Lagging? Try the Dendy graphics — they are lighter.":"Zwalnia? Włącz grafikę Dendy — jest lżejsza.",
"Turn on Dendy":"Włącz Dendy",
