"Pause: resume, restart, training, graphics, settings, main menu":"Pauza: wznów, od nowa, szkolenie, grafika, ustawienia, menu główne",
"Menu: pause, restart, training, graphics, settings":"Menu: pauza, od nowa, szkolenie, grafika, ustawienia",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Przytrzymaj palec na ziemi ~0,3 s — telefon zawibruje i pojawi się żółty pierścień — a potem, nie puszczając, przeciągnij: powstanie ramka. Albo użyj przycisku „Ramka” po prawej. Można też po prostu dotknąć oddziału.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Pełny ekran na iPhonie: „Udostępnij” ⬆ → „Dodaj do ekranu początkowego” — gra otworzy się bez pasków Safari.",
"Open portal-meteor.pages.dev for that.":"Otwórz w tym celu stronę portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Dotknięcie — wybierz · dotknięcie ziemi — idź · przytrzymanie — menu rozkazów · przytrzymanie i przesunięcie — ramka · 2 palce — przybliżanie",
"Robo-ninja":"Robo-ninja",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Bohaterka-zabójczyni: zrywy-teleporty, katana, shurikeny. Sama skacze po strefach wroga i tnie roboty na kawałki. 1 na stronę.",
"Shadow protocol":"Protokół Cienia",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Badanie: odblokowuje robo-ninja w Koszarach. Wymaga ukończonej fabryki mechów.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Bohaterka (1 na stronę): sama teleportuje się po strefach wroga i tnie roboty na kawałki; możesz ją przejąć i grać ręcznie.",
"is ready. She works on her own (AUTO) — possess her to play manually":"jest gotowa. Działa sama (AUTO) — przejmij ją, by grać ręcznie",
"Robo-ninja ready for action":"Robo-ninja gotowa do walki",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ Zwiad: wróg ma robo-ninja!",
"Warning! The enemy has a robo-ninja. Stay together":"Uwaga! Wróg ma robo-ninja. Trzymajcie się razem",
