"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ POJEDYNEK NINJA! Blok tuż przed ciosem to parowanie, zryw to unik. Wypatruj błysku zamachu",
"The two ninjas have met in a duel!":"Dwie ninja spotkały się w pojedynku!",
"⚔ Duel won! Our ninja prevails":"⚔ Pojedynek wygrany! Nasza ninja jest silniejsza",
"⚔ Duel lost…":"⚔ Pojedynek przegrany…",
"ninja duel":"pojedynek ninja",
"POSTURE BROKEN":"POSTAWA ZŁAMANA",
