"Teleport: aim at the ground (up to 150 m)":"Teleport: wyceluj w ziemię (do 150 m)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AUTO: sama skacze po strefach wroga i tnie. Drążek / WASD wstrzymuje na 1,5 s",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Ręczne: dotknij wroga — zryw i cios, przesunięcie — zamach, 🛡 — blok",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Ręczne sterowanie: LPM — katana, PPM — blok, Shift — zryw, Q — shurikeny, G — teleport",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ninja: dotknij wroga — zryw i cięcie, przesunięcie po prawej — zamach, ● — cios, 🛡 — blok (w porę = parowanie), ⇑ — zryw, ✦ — shurikeny, ◎ — teleport, AUTO — sama",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ninja: LPM — katana (przytrzymaj — ciężkie cięcie), PPM — blok (w porę = parowanie), Shift/Z — zryw, Q — shurikeny, G — teleport do celownika, skok w powietrzu — podwójny skok / bieg po ścianie, {0} — AUTO",
