"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Radio Portal Meteor: ponad 100 utworów EDMITRY prosto w grze — przycisk 📻 (PC: klawisz 5, [ ] — utwór). Muzyka ładuje się przez sieć i nie obciąża gry; głośność i autostart w Ustawieniach oraz link „Słuchaj na Spotify”.",
