"Radio: start by itself in battle":"Radio: włączaj samo w walce",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-ninja: cyborg z kataną. Odblokowuje się w Koszarach badaniem „Protokół Cienia” (wymaga fabryki mechów). Sama teleportuje się do stref wroga, tnie przeciwników na kawałki (bez krwi — iskry), wykonuje zrywy, rzuca shurikenami, pojedynkuje się z wrogim ninja. Przejmij ją — tryb AUTO lub sterowanie ręczne (na telefonie — własne przyciski).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Radio Portal Meteor: 103 utwory EDMITRY prosto w grze. Klawisz 5 (można zmienić), na telefonie — ☰ → Ustawienia → Dźwięk. Głośność i „włączaj samo w walce” w ustawieniach; muzyka cichnie przy wybuchach i głosie radia.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Nowe języki: uzbecki i tadżycki — w pełni; chiński, hiszpański, portugalski — częściowo. Nowy wybór języka w menu obok „Nowy mecz”.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Telefon: „ukryj ikony” 👁 zbiera pozostałe przyciski w zgrabną kolumnę przy prawej krawędzi; tryb pionowy już się nie nakłada; iPhone — gra nie koliduje z gestami Safari, a „Udostępnij → Dodaj do ekranu początkowego” uruchamia ją na pełnym ekranie.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Z v7.8.1: menu ☰ w rogu (pauza, od nowa, szkolenie, grafika), bez auto-Dendy, przycisk akcji ✋ na telefonie. v7.8.1 i v7.8 zostały w menu „🕘 Wersja gry”.",
