"Consortium. Boss: 15000 hull, cannon, 2 MGs, rockets. Very slow. Weak spot — the rear. One per army.":"Konsorcjum. Boss: 15000 pancerza, działo, 2 karabiny maszynowe, rakiety. Bardzo wolny. Słaby punkt — tył. Jeden na armię.",
"Walker \"Reaper\"":"Chodziak „Żniwiarz”",
