"Swarm. Squads within 70 m of the burrow (and selected ones), plus selected light/medium vehicles (Jackal, Hammer, Grad), go through the tunnel. Or: select and RMB/tap the burrow.":"Rój. Oddziały w promieniu 70 m od nory (i zaznaczone) oraz zaznaczone lekkie/średnie pojazdy („Szakal”, „Młot”, „Grad”) przechodzą tunelem i wychodzą na drugim końcu. Albo: zaznacz i kliknij PPM/dotknij norę.",
