"\"Bastion\" and \"Reaper\": from 12:00 (skipped here), plant, assembly, orders, weak spots, possession":"„Bastion” i „Żniwiarz”: od 12:00 (w lekcji przewinięte), zakład, montaż, rozkazy, słabe punkty, przejęcie",
