"Select a unit → \"▶ Possess\" or double-tap. Mode button at the top right: Strategist → Commander → Shooter.":"Zaznacz jednostkę → „▶ Przejmij” albo dotknij dwa razy. Przycisk trybu u góry po prawej: Strateg → Dowódca → Strzelec.",
"Select a unit → \"▶ Possess\" or double-click. {0} cycles: Strategist → Commander → Shooter.":"Zaznacz jednostkę → „▶ Przejmij” albo kliknij dwa razy. {0} — w kółko: Strateg → Dowódca → Strzelec.",
