"Living world: requests, hero quests, breakthrough ops":"Żywy świat: prośby swoich, zadania bohaterów, przełom w walce",
"Living world":"Żywy świat",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Swoi proszą o pomoc i nagradzają, bohaterowie dają zadania, przeciągający się front łamie się operacją",
"A request":"Prośba swoich",
"Breakthrough":"Przełom",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Swoi czasem proszą o pomoc: głos w radiu, karta „PROŚBA” i znacznik ✋. Oddział przyszpilono — zniszcz wrogów obok niego. Nagroda: żołnierz kapsułą desantową z bazy, karabin z paki łazika, miejsce strzelca albo osłona z orbity. Nie chcesz — ✕ albo po prostu zignoruj.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Doświadczony zwiadowca „Puchacz” proponuje zadanie. Y — przyjmij (N — odmów). Idź do znacznika ★, zdejmij ochronę i postój przy pilocie 3 s — dołączy do twojego oddziału.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Front stanął — sztab proponuje przełom. Y — przyjmij. Utrzymaj przekaźnik 8 s bez wrogów w pobliżu: mapa wroga będzie widoczna 60 s. Generator — wieżyczki wroga milczą 2 min. W trybie Strategist — „Przydziel oddziałowi”. Wróg też tak potrafi: pilnuj ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Swoi proszą o pomoc: karta „PROŚBA” i znacznik ✋. Zniszcz wrogów obok przyszpilonego oddziału — dostaniesz nagrodę. ✕ — pomiń.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Bohater „Puchacz” proponuje zadanie — dotknij „Przyjmij”. Idź do ★, zdejmij ochronę, postój przy pilocie.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Front stanął — dotknij „Przyjmij” i utrzymaj przekaźnik 8 s: mapa wroga otworzy się na minutę.",
"Pod redeploy from the base: {0} m — through the sky portal":"Przerzut kapsułą z bazy: {0} m — przez portal niebios",
"Pod away from the base! Hold on — exit over the target.":"Kapsuła wyruszyła z bazy! Trzymajcie się — wyjście nad celem.",
"Landed at the objective!":"Desant przy celu!",
"LAUNCH FROM BASE":"START Z BAZY",
"LANDING":"LĄDOWANIE",
"REDEPLOY":"PRZERZUT",
"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"Stalowy puch się przykleił — zżera pancerz −2/s. Postój 3 s poza walką albo idź do inżyniera",
"An engineer brushed the fluff off":"Inżynier oczyścił puch",
"The fluff fell off — armour is safe":"Puch opadł — pancerz cały",
"The firefly swarm scattered by the blast":"Rój świetlików rozpędzony wybuchem",
