"Lefty's convoy is ready: two Jackals. Stay close — they wait for you":"Konwój „Mańkuta” gotowy: dwa „Szakale”. Trzymaj się blisko — czekają na ciebie",
"The convoy is waiting for you":"Konwój na ciebie czeka",
"Ambush! Cover the Jackals!":"Zasadzka! Osłaniaj „Szakale”!",
"the convoy made it ({0} of 2)! +2 CP, +150 ore, the Jackals are yours":"konwój dotarł ({0} z 2)! +2 PD, +150 rudy, „Szakale” są twoje",
