"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"Podstawowy czołg: działo i karabin maszynowy. Konsorcjum ma „Buldoga” (wytrzymalszy), Chmara — „Pająka” (szybszy).",
"Heavy tank":"Ciężki czołg",
"Autonomous flying gunner: fast, fragile, fears anti-air.":"Autonomiczny latający strzelec: szybki, kruchy, boi się obrony przeciwlotniczej.",
"Upgrade":"Ulepszenie",
"Longer, faster jetpacks for all infantry.":"Dalsze i szybsze jetpacki dla całej piechoty.",
"Extractors mine more ore.":"Ekstraktory wydobywają więcej rudy.",
"Army-wide levels: less damage taken / more damage dealt.":"Poziomy dla całej armii: mniej obrażeń od wroga / więcej obrażeń zadawanych wrogowi.",
"Levels":"Poziomy",
"Base":"Baza",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Serce bazy: oddziały, inżynierowie, kapsuły, badania. Utrata HQ oznacza porażkę.",
"Produces: ":"Produkuje: ",
"Launch pad":"Platforma startowa",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Silos przy HQ: stąd startują kapsuły, skrzynie z zaopatrzeniem i bombowce — przez niebiański portal do celu. Nie można tu budować.",
"Economy":"Ekonomia",
"Key building":"Kluczowy budynek",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Słaby punkt — tył (silnik): obrażenia ×{0}. Działo, 2 wieżyczki z karabinami, wyrzutnia rakiet; obraca się bardzo wolno — atakuj z flanki.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Słaby punkt — świecący rdzeń pod brzuchem: obrażenia od dołu ×{0}. Promień zniekształcenia i tupnięcie obszarowe; przekracza zapory — trzymaj dystans, nie stój w kupie.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Skuteczne: bomby lotnicze i artyleria (×{0}), rakiety (×{1}), bombardowanie dywanowe; pociski ledwo go drapią (×{2}).",
"Faction":"Frakcja",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Szybkie maszyny, roje dronów, tunele i regeneracja. Lżejsza, ale szybsza piechota; działa i szyny biją mocniej.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Ciężka piechota w pancerzach wspomaganych, betonowe zapory, naprawy i artyleria. Wolniejsza, ale wytrzymalsza.",
