"Three modes on one button: Shooter (you fight yourself), the new Commander (lead one squad, 4 abilities per unit type) and Strategist. On the phone — a simple interface: fewer buttons, modes unlock during the battle.":"Trzy tryby jednym przyciskiem: Strzelec (sam walczysz), nowy Dowódca (prowadzisz jeden oddział, 4 zdolności na typ jednostki) i Strateg. Na telefonie — prosty interfejs: mniej przycisków, tryby odblokowują się w trakcie walki.",
"Living meteor: rocks, ridges, a hangar in a mesa, lava / ice / methane lakes, three biomes, local weather, new anomalies and native fauna.":"Żywy meteor: skały, grzbiety, hangar w górze stołowej, jeziora lawy, lodu i metanu, trzy biomy, lokalna pogoda, nowe anomalie i miejscowa fauna.",
"Factions play differently: the Swarm digs tunnels and regenerates, the Consortium builds barriers and repairs. From minute 12 — the Bastion and Reaper bosses; you can possess your own.":"Frakcje grają inaczej: Rój kopie tunele i się leczy, Konsorcjum stawia zapory i naprawia sprzęt. Od 12. minuty — bossowie „Bastion” i „Żniwiarz”; możesz przejąć własnego.",
"Living world: your troopers ask for help over the radio (with a reward), heroes give quests, a stalled front gets a \"Breakthrough\" operation. Capsules, crates and strikes launch from the base through the sky portal.":"Żywy świat: twoi żołnierze proszą o pomoc przez radio (za nagrodę), bohaterowie dają zadania, gdy front stoi — operacja „Przełom w walce”. Kapsuły, skrzynie i uderzenia startują z bazy przez niebiański portal.",
"Faster (a frame up to 2x cheaper), gamepad in every mode, tablet layout, an encyclopedia of everything in the game, feedback mode — a note with a screenshot on one key.":"Szybciej (klatka nawet 2 razy tańsza), gamepad we wszystkich trybach, układ na tablet, encyklopedia wszystkiego w grze, tryb opinii — notatka ze zrzutem ekranu jednym klawiszem.",
"All new texts are translated into Uzbek, Tajik, Chinese, Spanish, Portuguese and Hebrew. The v7.9 ninja and radio stay; v7.9 is in the \"🕘 Game version\" menu.":"Wszystkie nowe teksty przetłumaczono na uzbecki, tadżycki, chiński, hiszpański, portugalski i hebrajski. Robo-ninja i radio z v7.9 zostają; v7.9 jest w menu „🕘 Wersja gry”.",
